<?php
require __DIR__.'/../includes/bootstrap.php';$u=require_can('visit.view');v2_require();$id=get_int('id');$v=visit_find($id);
if(!$v)abort(404,'Not found','Visit not found.');if(!can_access_visit($v))deny('This visit is outside your scope.');
$open=$v['status']==='OPEN';$owner=can_write_exam($v);$editable=$owner&&$open&&$v['clinical_status']!=='COMPLETED';
$cur=exam_current($id);$exams=exams_for_visit($id);$note=visit_note_latest($id);$med=med_latest((int)$v['patient_id']);
$items=q_all('SELECT i.*,u.display_name FROM clinical_item i JOIN user_account u ON u.user_id=i.recorded_by WHERE visit_id=? ORDER BY item_id DESC',[$id]);
$saved=$_SESSION['visit_input']??[];$input=($saved['visit_id']??0)===$id?($saved['data']??[]):[];unset($_SESSION['visit_input']);
page_start($v['patient_name'],['nav'=>'visits','subtitle'=>$v['patient_code'].' · '.$v['visit_no'].' · '.$v['doctor_name'],'actions'=>'<a class="btn btn-secondary" href="'.e(url('patients/view.php?id='.$v['patient_id'])).'">Patient profile</a> '.status_badge($v['status'])]);
?>
<div class="workspace-banner"><div><span class="eyebrow">Clinical workspace</span><h2><?= e(label($v['workflow_mode'])) ?> visit</h2><p><?= e(label($v['visit_type'])) ?> · Started <?= e(fmt_dt($v['visited_at'])) ?></p></div><div class="status-pair"><div><small>Clinical work</small><?= $v['workflow_mode']==='LEGACY'?badge('Not tracked','muted'):status_badge($v['clinical_status']) ?></div><div><small>Reception review</small><?= $v['workflow_mode']==='LEGACY'?badge('Not tracked','muted'):status_badge($v['administrative_status']) ?></div></div></div>
<?php if($med && $med['allergies']):?><div class="alert alert-warn"><strong>Allergy alert:</strong> <?= e(implode(', ',array_column($med['allergies'],'allergen_name'))) ?>. <a href="<?= e(url('histories/medical.php?patient_id='.$v['patient_id'])) ?>">Review medical history</a></div><?php else:?><div class="alert alert-info"><a href="<?= e(url('histories/medical.php?patient_id='.$v['patient_id'])) ?>">Review medical history</a> · <?= !$med?'No medical history recorded.':($med['allergy_status']==='NONE_REPORTED'?'No known allergies recorded.':'Check the recorded allergy status before treatment.') ?></div><?php endif;?>
<div class="workspace-grid"><div>
<section class="panel"><div class="row-between"><h2>Clinical note</h2><span class="badge badge-muted">Revision history retained</span></div>
<?php if($editable):?><form method="post" action="<?= e(url('visits/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="action" value="note">
<?= f_textarea('clinical_note','Complaint, assessment and care provided',$input+['clinical_note'=>$note['note']??''],[],['rows'=>5,'hint'=>'Quick visits require a saved note. Every save creates a revision.','required'=>true]) ?><button class="btn btn-primary">Save clinical note</button></form>
<?php elseif($note):?><p class="pre"><?= e($note['note']) ?></p><?php else:?><p class="muted">No clinical note recorded.</p><?php endif;?>
<?php if($note):?><p class="hint">Last saved <?= e(fmt_dt($note['created_at'])) ?> by <?= e($note['display_name']) ?></p><details><summary>Previous note revisions</summary><?php foreach(q_all('SELECT r.*,u.display_name FROM visit_note_revision r JOIN user_account u ON u.user_id=r.authored_by WHERE visit_id=? ORDER BY revision_id DESC',[$id]) as $rev):?><div class="revision"><strong><?= e(fmt_dt($rev['created_at']).' · '.$rev['display_name']) ?></strong><p class="pre"><?= e($rev['note']) ?></p></div><?php endforeach;?></details><?php endif;?></section>
<section class="panel"><div class="row-between"><h2>Examination</h2><?php if($editable && !$cur):?><a class="btn btn-secondary" href="<?= e(url('examinations/form.php?visit_id='.$id)) ?>">Start examination</a><?php elseif($editable && $cur['status']==='DRAFT'):?><a class="btn btn-primary" href="<?= e(url('examinations/form.php?id='.$cur['exam_id'])) ?>">Continue draft</a><?php endif;?></div>
<p class="muted"><?= $v['workflow_mode']==='QUICK'?'Optional for a Quick visit. Upgrade to Standard for a full assessment.':'Standard visits need a finalized examination before clinical completion.' ?></p>
<?php foreach($exams as $ex):?><div class="record-row"><a href="<?= e(url('examinations/view.php?id='.$ex['exam_id'])) ?>">Examination #<?= (int)$ex['exam_id'] ?> · <?= e(fmt_dt($ex['examined_at'])) ?></a><?= status_badge($ex['status']) ?></div><?php endforeach;?></section>
<section class="panel"><h2>Dental findings & treatment</h2><p class="muted">Findings describe observations. Recommendations are proposed care. Performed treatments record care actually delivered.</p>
<?php if($editable):?><form method="post" action="<?= e(url('visits/action.php')) ?>" id="clinical-item-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="action" value="item">
<?= f_select('item_type','Record type',['FINDING'=>'Clinical finding','RECOMMENDATION'=>'Treatment recommendation','PROCEDURE'=>'Performed treatment'],$input,[],['placeholder'=>'Choose what you are recording','required'=>true]) ?>
<details class="tooth-picker" open><summary>Select teeth · FDI numbering</summary><p class="hint">Patient’s right is on your left. Select one or more teeth, or leave blank for a general oral finding.</p>
<?php foreach(['Permanent upper'=>[range(18,11),range(21,28)],'Permanent lower'=>[range(48,41),range(31,38)],'Primary upper'=>[range(55,51),range(61,65)],'Primary lower'=>[range(85,81),range(71,75)]] as $label=>$arches):?><div class="arch-label"><?= e($label) ?></div><div class="tooth-arch"><?php foreach($arches as $arch):?><div class="tooth-quadrant"><?php foreach($arch as $tooth):?><button class="tooth" type="button" data-tooth="<?= $tooth ?>" aria-pressed="false" aria-label="Tooth <?= $tooth ?>"><span class="tooth-shape"></span><?= $tooth ?></button><?php endforeach;?></div><?php endforeach;?></div><?php endforeach;?></details>
<div class="grid-2"><?= f_text('teeth','Selected teeth',$input,[],['hint'=>'FDI numbers separated by commas, e.g. 11,12. You can also type them.']) ?><?= f_text('surfaces','Surfaces (optional)',$input,[],['hint'=>'M mesial · D distal · O occlusal · I incisal · B buccal · L lingual · P palatal. Comma-separated.']) ?></div>
<?= f_textarea('description','Description',$input,[],['rows'=>3,'required'=>true,'hint'=>'Describe the selected record type. Recording a recommendation does not mark it performed.']) ?><button class="btn btn-primary">Add clinical record</button></form><?php endif;?>
<?php foreach(['FINDING'=>'Findings','RECOMMENDATION'=>'Recommendations','PROCEDURE'=>'Performed treatments'] as $type=>$title):?><h3 class="section-label"><?= e($title) ?></h3><?php $filtered=array_filter($items,fn($r)=>$r['item_type']===$type);if(!$filtered):?><p class="muted">None recorded.</p><?php endif;foreach($filtered as $r):?><article class="clinical-record <?= $r['voided_at']?'voided':'' ?>"><div class="row-between"><strong><?= $r['teeth']?'Teeth '.e($r['teeth']):'General / whole mouth' ?> <?= e($r['surfaces']??'') ?></strong><?php if($r['voided_at']):?><?= badge('Voided','muted') ?><?php endif;?></div><p class="pre"><?= e($r['description']) ?></p><small class="muted"><?= e($r['display_name'].' · '.fmt_dt($r['recorded_at'])) ?></small>
<?php if($r['voided_at']):?><p class="hint">Reason: <?= e($r['void_reason']) ?></p><?php elseif($editable):?><details><summary>Correct a mistake</summary><form method="post" action="<?= e(url('visits/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="item_id" value="<?= (int)$r['item_id'] ?>"><input type="hidden" name="action" value="void_item"><?= f_textarea('reason','Reason to void this entry',[],[],['required'=>true]) ?><button class="btn btn-danger btn-sm">Void entry; retain history</button><p class="hint">Then add the corrected entry above.</p></form></details><?php endif;?></article><?php endforeach;endforeach;?></section>
</div><aside class="workspace-aside"><section class="panel"><span class="eyebrow">Next steps</span><h2>Finish this visit</h2>
<?php if(!$open):?><p>This visit is <?= e(strtolower($v['status'])) ?>. Finalized examinations can be corrected through their own record page.</p>
<?php else:?>
<?php if($editable && $v['workflow_mode']!=='STANDARD'):?><form method="post" action="<?= e(url('visits/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="action" value="mode"><?= f_select('mode','Visit workflow',$v['workflow_mode']==='QUICK'?['STANDARD'=>'Standard']:['QUICK'=>'Quick','STANDARD'=>'Standard'],[],[]) ?><button class="btn btn-secondary btn-block"><?= $v['workflow_mode']==='QUICK'?'Upgrade to Standard':'Set workflow' ?></button><p class="hint">Existing notes and clinical records are retained.</p></form><?php endif;?>
<div class="step-card"><strong>1. Clinical completion</strong><p class="hint">Doctor confirms the clinical record is finished.</p><?php if($editable):?><?= post_button('visits/action.php',['id'=>$id,'action'=>'clinical_complete'],'Complete clinical work','btn-primary','Complete clinical work? Notes and treatment entries become read-only.') ?><?php else:?><?= $v['workflow_mode']==='LEGACY'?badge('Not tracked','muted'):status_badge($v['clinical_status']) ?><?php endif;?></div>
<div class="step-card"><strong>2. Reception review</strong><p class="hint">Confirm patient details and follow-up arrangements. This does not record payment; billing is not included in this release.</p><?php if(can('appointment.write') && $v['administrative_status']!=='COMPLETED'):?><form method="post" action="<?= e(url('visits/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="action" value="admin_complete"><?= f_check('confirm_review','Patient details and follow-up reviewed.') ?><button class="btn btn-secondary">Complete reception review</button></form><?php else:?><?= $v['workflow_mode']==='LEGACY'?badge('Not tracked','muted'):status_badge($v['administrative_status']) ?><?php endif;?></div>
<?php if(can_close_visit($v) && $v['clinical_status']==='COMPLETED' && $v['administrative_status']==='COMPLETED'):?><?= post_button('visits/close.php',['id'=>$id],'Close completed visit','btn-primary','Close the visit and complete its linked appointment?') ?><?php else:?><p class="hint">Close becomes available when both steps are complete.</p><?php endif;?>
<?php if($editable && !$note && !$items && !$cur):?><details class="drop"><summary class="btn btn-ghost btn-sm">Opened by mistake?</summary><form method="post" action="<?= e(url('visits/cancel.php')) ?>" class="drop-body"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><?= f_select('reason_code','Cancellation reason',clinic('visit_cancel_reasons'),[],[],['placeholder'=>'Choose reason','required'=>true]) ?><button class="btn btn-danger">Cancel empty visit</button></form></details><?php endif;endif;?></section>
<section class="panel"><h3>Reception handover</h3><p class="pre"><?= e($v['note']?:'No reception note.') ?></p><?php if(can('appointment.write')):?><a href="<?= e(url('appointments/form.php?patient_id='.$v['patient_id'])) ?>">Book follow-up appointment →</a><?php endif;?></section>
</aside></div><script src="<?= e(url('assets/js/clinical.js')) ?>"></script><?php page_end();
